pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public { c = new MY_BANK(address(this)); }

    function testFuzz_property(address sender, uint256 amount, uint256 unlockTime) public {
        amount = bound(amount, 1 wei, 10 ether);
        vm.assume(sender != address(0));

        vm.deal(sender, amount);
        vm.prank(sender);
        try c.Put{value: amount}(unlockTime) {
        } catch {
        }

        uint len = History.length;
        if (len == 0) {
            assertTrue(false);
        }

        Message memory m = History[len - 1];
        assertTrue(keccak256(bytes(m.Data)) == keccak256(bytes("Put")));
    }

    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message public LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
